import test from 'node:test';
import assert from 'node:assert/strict';
import { allocateShares } from './split.mjs';

test('allocates every cent and distributes remainder fairly', () => {
  assert.deepEqual(allocateShares(1000, 4), [250, 250, 250, 250]);
  assert.deepEqual(allocateShares(1001, 3), [334, 334, 333]);
  assert.deepEqual(allocateShares(1, 3), [1, 0, 0]);
  for (const [total, people] of [[1001, 3], [1, 3], [999999, 1000]]) {
    assert.equal(allocateShares(total, people).reduce((sum, amount) => sum + amount, 0), total);
  }
});

test('rejects invalid totals and people counts', () => {
  for (const total of [0, -1, 1.5, NaN, Infinity]) assert.throws(() => allocateShares(total, 2));
  for (const people of [0, -1, 1.5, 1001, NaN]) assert.throws(() => allocateShares(100, people));
});

test('visible app includes required labels, validation, and reset behavior', async () => {
  const { readFile } = await import('node:fs/promises');
  const html = await readFile(new URL('./index.html', import.meta.url), 'utf8');
  const app = await readFile(new URL('./app.mjs', import.meta.url), 'utf8');
  assert.ok(html.includes('Bill total in dollars'));
  assert.ok(html.includes('Number of people'));
  assert.ok(html.includes('type=\"reset\">Reset'));
  assert.ok(app.includes('whole number of people from 1 to 1,000'));
  assert.ok(app.includes("form.addEventListener('reset'"));
  assert.ok(app.includes('share / 100'));
});
